package com.hrms.assignment.controller;
import com.hrms.assignment.dto.*;import com.hrms.assignment.service.AssignmentService;import com.hrms.auth.security.AuthPrincipal;import com.hrms.common.responses.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin") @Tag(name="Employee work assignments") @SecurityRequirement(name="bearerAuth") @PreAuthorize("hasRole('ADMIN')")
public class AssignmentController {private final AssignmentService service;private final ClockSource clock;public AssignmentController(AssignmentService s,ClockSource c){service=s;clock=c;}
 @PostMapping("/employees/{employeeId}/work-assignments") public ApiResponse<AssignmentResponse> create(@PathVariable String employeeId,@Valid @RequestBody CreateAssignmentRequest r,@AuthenticationPrincipal AuthPrincipal a){return ApiResponse.success("Work assignment created",service.create(employeeId,r,a),clock);}
 @GetMapping("/employees/{employeeId}/work-assignments") public ApiResponse<java.util.List<AssignmentResponse>> list(@PathVariable String employeeId){return ApiResponse.success("Work assignments retrieved",service.list(employeeId),clock);}
 @GetMapping("/work-assignments/{assignmentId}") public ApiResponse<AssignmentResponse> get(@PathVariable String assignmentId){return ApiResponse.success("Work assignment retrieved",service.get(assignmentId),clock);}
 @PatchMapping("/work-assignments/{assignmentId}/end") public ApiResponse<AssignmentResponse> end(@PathVariable String assignmentId,@Valid @RequestBody EndAssignmentRequest r,@AuthenticationPrincipal AuthPrincipal a){return ApiResponse.success("Work assignment ended",service.end(assignmentId,r,a),clock);}}
